-- Rollback-only real PostgreSQL behavior, not hosted Auth/Realtime evidence.
begin;
create function pg_temp.community_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'COMMUNITY FAILED: %',label;end if;end$$;
create function pg_temp.community_denied(statement text,expected text default '42501') returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=expected then return;end if;raise exception 'Expected %, got %: %',expected,sqlstate,sqlerrm;end;raise exception 'COMMUNITY wrongly permitted %',statement;end$$;
